-- LOCAL ONLY: never apply remotely without approval. Private bucket; server-only mutations after owner RPC proof.
begin;
-- Hosted Supabase runs this migration as `postgres`. PostgreSQL requires the
-- caller of ALTER FUNCTION ... OWNER TO to be able to SET ROLE to the target
-- owner, and the target owner must temporarily have CREATE on the function's
-- schema. Keep both grants scoped to this transaction and revoke them after
-- ownership has moved.
do $$ begin
  if not exists(select 1 from pg_roles where rolname='receipt_lifecycle_owner') then
    create role receipt_lifecycle_owner nologin noinherit nosuperuser nocreatedb nocreaterole noreplication;
  end if;
exception when insufficient_privilege then
  raise exception 'receipt_lifecycle_owner must be provisioned by a Supabase database administrator before this migration';
end $$;
grant receipt_lifecycle_owner to postgres;
grant usage, create on schema public to receipt_lifecycle_owner;
-- Hosted Supabase grants postgres USAGE on auth but not grant option, so a
-- custom owner cannot be given direct auth schema access. These two narrowly
-- scoped postgres-owned helpers preserve the request JWT identity without
-- broad role membership or BYPASSRLS.
create function public.receipt_auth_uid() returns uuid language sql stable security definer set search_path=pg_catalog,auth as $$ select auth.uid() $$;
create function public.receipt_auth_role() returns text language sql stable security definer set search_path=pg_catalog,auth as $$ select auth.role() $$;
revoke all on function public.receipt_auth_uid(), public.receipt_auth_role() from public, anon, authenticated, service_role;
grant execute on function public.receipt_auth_uid(), public.receipt_auth_role() to receipt_lifecycle_owner;
create table public.receipts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null unique, original_filename text not null, mime_type text not null check(mime_type in('image/jpeg','image/png','image/webp')), file_size integer not null check(file_size between 1 and 5242880), sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'), status text not null default 'uploaded' check(status in('uploaded','processing','review_required','confirmed','failed','deleting')), extraction jsonb not null default '{}'::jsonb,warnings jsonb not null default '[]'::jsonb,error_code text,ai_model text,prompt_version text,transaction_id uuid unique references public.expense_transactions(id),attempts integer not null default 0 check(attempts<=5),processing_started_at timestamptz,processing_lease_id uuid,confirmed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index receipts_owner_created_idx on public.receipts(user_id,created_at desc); create index receipts_owner_status_idx on public.receipts(user_id,status); alter table public.receipts enable row level security; create policy receipts_select_own on public.receipts for select to authenticated using(auth.uid()=user_id);
-- SECURITY DEFINER does not bypass RLS. These narrowly scoped policies let the
-- dedicated owner operate only for the request JWT's user, except server-only
-- completion/failure calls whose JWT role is service_role.
create policy receipts_lifecycle_owner_select on public.receipts for select to receipt_lifecycle_owner using (user_id = public.receipt_auth_uid() or public.receipt_auth_role() = 'service_role');
create policy receipts_lifecycle_owner_insert on public.receipts for insert to receipt_lifecycle_owner with check (user_id = public.receipt_auth_uid());
create policy receipts_lifecycle_owner_update on public.receipts for update to receipt_lifecycle_owner using (user_id = public.receipt_auth_uid() or public.receipt_auth_role() = 'service_role') with check (user_id = public.receipt_auth_uid() or public.receipt_auth_role() = 'service_role');
create policy receipts_lifecycle_owner_delete on public.receipts for delete to receipt_lifecycle_owner using (user_id = public.receipt_auth_uid());
create policy expense_transactions_lifecycle_owner_select on public.expense_transactions for select to receipt_lifecycle_owner using (user_id = public.receipt_auth_uid());
create policy expense_transactions_lifecycle_owner_insert on public.expense_transactions for insert to receipt_lifecycle_owner with check (user_id = public.receipt_auth_uid());
create policy expense_transactions_lifecycle_owner_delete on public.expense_transactions for delete to receipt_lifecycle_owner using (user_id = public.receipt_auth_uid());
-- Conservative fail-closed policy rule: this feature creates no browser Storage
-- policies. Any broad/public/authenticated/anon storage.objects policy, or any
-- receipts-referencing policy, must be reviewed and removed before migration.
do $$ begin if exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and (roles && array['public','anon','authenticated']::name[] or coalesce(qual,'')='' or coalesce(with_check,'')='' or coalesce(qual,'') ilike '%receipts%' or coalesce(with_check,'') ilike '%receipts%')) then raise exception 'Precondition failed: review/remove broad or receipts Storage object policies before applying this migration'; end if; end $$;
insert into storage.buckets(id,name,public) values('receipts','receipts',false) on conflict(id) do update set public=false;
create function public.receipt_owner_trigger() returns trigger language plpgsql set search_path=pg_catalog,public as $$ begin if new.transaction_id is not null and not exists(select 1 from public.expense_transactions t where t.id=new.transaction_id and t.user_id=new.user_id) then raise exception 'receipt transaction owner mismatch'; end if; return new; end $$;
create trigger receipts_transaction_owner before insert or update of transaction_id,user_id on public.receipts for each row execute function public.receipt_owner_trigger();
create function public.create_receipt_upload(p_filename text,p_mime_type text,p_file_size integer,p_sha256 text) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; v uuid:=public.receipt_auth_uid(); v_receipt_id uuid:=gen_random_uuid(); begin if v is null then raise exception 'authentication required'; end if; insert into public.receipts(id,user_id,storage_path,original_filename,mime_type,file_size,sha256) values(v_receipt_id,v,v::text||'/'||v_receipt_id::text||'/original',left(p_filename,150),p_mime_type,p_file_size,p_sha256) returning * into r; return r; end $$;
create function public.start_receipt_processing(p_receipt_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin select * into r from public.receipts where id=p_receipt_id and user_id=public.receipt_auth_uid() for update; if not found then raise exception 'receipt not found'; end if; if r.status='processing' and r.processing_started_at > now()-interval '10 minutes' then raise exception 'receipt is already processing'; end if; if r.status='processing' then update public.receipts set status='failed',error_code='PROCESSING_LEASE_EXPIRED',processing_started_at=null,processing_lease_id=null,updated_at=now() where id=r.id returning * into r; end if; if r.status not in('uploaded','failed','review_required') or r.attempts >= 5 then raise exception 'receipt cannot be processed'; end if; update public.receipts set status='processing',attempts=attempts+1,processing_started_at=now(),processing_lease_id=gen_random_uuid(),updated_at=now() where id=r.id returning * into r; return r; end $$;
create function public.retry_receipt_processing(p_receipt_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin select * into r from public.receipts where id=p_receipt_id and user_id=public.receipt_auth_uid() for update; if not found or r.status not in('failed','review_required') then raise exception 'receipt cannot be retried'; end if; update public.receipts set status='uploaded',error_code=null,updated_at=now() where id=r.id returning * into r; return r; end $$;
create function public.server_complete_receipt_extraction(p_receipt_id uuid,p_processing_lease_id uuid,p_extraction jsonb,p_warnings jsonb) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin if public.receipt_auth_role() <> 'service_role' then raise exception 'server context required'; end if; update public.receipts set status='review_required',extraction=p_extraction,warnings=p_warnings,error_code=null,updated_at=now() where id=p_receipt_id and status='processing' and processing_lease_id=p_processing_lease_id returning * into r; if not found then raise exception 'receipt cannot be completed'; end if; return r; end $$;
create function public.server_mark_receipt_failed(p_receipt_id uuid,p_processing_lease_id uuid,p_error_code text) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin if public.receipt_auth_role() <> 'service_role' then raise exception 'server context required'; end if; update public.receipts set status='failed',error_code=left(p_error_code,80),updated_at=now() where id=p_receipt_id and status='processing' and processing_lease_id=p_processing_lease_id returning * into r; if not found then raise exception 'receipt cannot fail'; end if; return r; end $$;
create function public.begin_receipt_delete(p_receipt_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin select * into r from public.receipts where id=p_receipt_id and user_id=public.receipt_auth_uid() for update; if not found or r.transaction_id is not null then raise exception 'receipt cannot be deleted'; end if; if r.status='processing' and r.processing_started_at > now()-interval '10 minutes' then raise exception 'receipt is actively processing'; end if; if r.status='processing' then update public.receipts set status='failed',error_code='PROCESSING_LEASE_EXPIRED',processing_started_at=null,processing_lease_id=null,updated_at=now() where id=r.id returning * into r; end if; if r.status not in('uploaded','failed','review_required') then raise exception 'receipt cannot be deleted'; end if; update public.receipts set status='deleting',updated_at=now() where id=r.id returning * into r; return r; end $$;
create function public.finalize_receipt_delete(p_receipt_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin delete from public.receipts where id=p_receipt_id and user_id=public.receipt_auth_uid() and status='deleting' returning * into r; if not found then raise exception 'receipt cannot be finalized'; end if; return r; end $$;
create function public.begin_confirmed_receipt_transaction_delete(p_transaction_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin select * into r from public.receipts where transaction_id=p_transaction_id and user_id=public.receipt_auth_uid() for update; if not found then raise exception 'linked receipt not found'; end if; if r.status not in ('confirmed','deleting') then raise exception 'linked receipt cannot be deleted'; end if; if r.status='confirmed' then update public.receipts set status='deleting',updated_at=now() where id=r.id returning * into r; end if; return r; end $$;
create function public.finalize_confirmed_receipt_transaction_delete(p_receipt_id uuid,p_transaction_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; tx public.expense_transactions; begin select * into r from public.receipts where id=p_receipt_id and transaction_id=p_transaction_id and user_id=public.receipt_auth_uid() and status='deleting' for update; if not found then raise exception 'linked receipt cannot be finalized'; end if; delete from public.receipts where id=r.id returning * into r; delete from public.expense_transactions where id=p_transaction_id and user_id=public.receipt_auth_uid() returning * into tx; if not found then raise exception 'linked transaction not found'; end if; return jsonb_build_object('receipt',to_jsonb(r),'transaction',to_jsonb(tx)); end $$;
create function public.authorize_receipt_preview(p_receipt_id uuid) returns public.receipts language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; begin select * into r from public.receipts where id=p_receipt_id and user_id=public.receipt_auth_uid() and status<>'deleting'; if not found then raise exception 'receipt not found'; end if; return r; end $$;
create function public.confirm_receipt_transaction(p_receipt_id uuid,p_final_transaction jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare r public.receipts; tx public.expense_transactions; v uuid:=public.receipt_auth_uid(); begin select * into r from public.receipts where id=p_receipt_id and user_id=v for update; if not found then raise exception 'receipt not found'; end if; if r.status='confirmed' then select * into tx from public.expense_transactions where id=r.transaction_id; return jsonb_build_object('receipt',to_jsonb(r),'transaction',to_jsonb(tx)); end if; if r.status<>'review_required' then raise exception 'receipt is not ready'; end if; if coalesce((p_final_transaction->>'amount')::numeric,0)<=0 or coalesce(p_final_transaction->>'merchant','')='' or coalesce(p_final_transaction->>'category','')='' or coalesce(p_final_transaction->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(p_final_transaction->>'type','') not in('income','expense') then raise exception 'invalid transaction'; end if; insert into public.expense_transactions(user_id,type,amount,transaction_date,category,merchant,note,items) values(v,p_final_transaction->>'type',(p_final_transaction->>'amount')::numeric,(p_final_transaction->>'date')::date,p_final_transaction->>'category',p_final_transaction->>'merchant',coalesce(p_final_transaction->>'note',''),coalesce(p_final_transaction->'items','[]'::jsonb)) returning * into tx; update public.receipts set status='confirmed',transaction_id=tx.id,confirmed_at=now(),updated_at=now() where id=r.id returning * into r; return jsonb_build_object('receipt',to_jsonb(r),'transaction',to_jsonb(tx)); end $$;
grant select,insert,update,delete on public.receipts to receipt_lifecycle_owner;
grant select,insert,delete on public.expense_transactions to receipt_lifecycle_owner;
alter function public.create_receipt_upload(text,text,integer,text) owner to receipt_lifecycle_owner; alter function public.start_receipt_processing(uuid) owner to receipt_lifecycle_owner; alter function public.retry_receipt_processing(uuid) owner to receipt_lifecycle_owner; alter function public.server_complete_receipt_extraction(uuid,uuid,jsonb,jsonb) owner to receipt_lifecycle_owner; alter function public.server_mark_receipt_failed(uuid,uuid,text) owner to receipt_lifecycle_owner; alter function public.begin_receipt_delete(uuid) owner to receipt_lifecycle_owner; alter function public.finalize_receipt_delete(uuid) owner to receipt_lifecycle_owner; alter function public.begin_confirmed_receipt_transaction_delete(uuid) owner to receipt_lifecycle_owner; alter function public.finalize_confirmed_receipt_transaction_delete(uuid,uuid) owner to receipt_lifecycle_owner; alter function public.authorize_receipt_preview(uuid) owner to receipt_lifecycle_owner; alter function public.confirm_receipt_transaction(uuid,jsonb) owner to receipt_lifecycle_owner;
-- The dedicated owner no longer needs schema CREATE or a membership path once
-- function ownership has been transferred. postgres retains its normal hosted
-- administrator privileges; this only removes the temporary grant.
revoke create on schema public from receipt_lifecycle_owner;
revoke receipt_lifecycle_owner from postgres;
revoke all on table public.receipts from public,anon,authenticated; grant select on public.receipts to authenticated; revoke all on function public.create_receipt_upload(text,text,integer,text),public.start_receipt_processing(uuid),public.retry_receipt_processing(uuid),public.server_complete_receipt_extraction(uuid,uuid,jsonb,jsonb),public.server_mark_receipt_failed(uuid,uuid,text),public.begin_receipt_delete(uuid),public.finalize_receipt_delete(uuid),public.begin_confirmed_receipt_transaction_delete(uuid),public.finalize_confirmed_receipt_transaction_delete(uuid,uuid),public.authorize_receipt_preview(uuid),public.confirm_receipt_transaction(uuid,jsonb) from public,anon; grant execute on function public.create_receipt_upload(text,text,integer,text),public.start_receipt_processing(uuid),public.retry_receipt_processing(uuid),public.begin_receipt_delete(uuid),public.finalize_receipt_delete(uuid),public.begin_confirmed_receipt_transaction_delete(uuid),public.finalize_confirmed_receipt_transaction_delete(uuid,uuid),public.authorize_receipt_preview(uuid),public.confirm_receipt_transaction(uuid,jsonb) to authenticated; grant execute on function public.server_complete_receipt_extraction(uuid,uuid,jsonb,jsonb),public.server_mark_receipt_failed(uuid,uuid,text) to service_role;
commit;
